package com.nextgensystems.mhambi.engine

import com.google.gson.Gson
import com.google.gson.JsonElement
import com.google.gson.JsonObject
import com.google.gson.annotations.SerializedName

/**
 * Typed view of assets/portal-config.json, the single screen definition shared with the website
 * (generated by shared/build-portal-config.js). Fields that may be absent are nullable on purpose.
 */
data class PortalConfig(
    val version: Int?,
    val roles: Map<String, RoleDef>,
    val pages: Map<String, PageDef>,
    val files: Map<String, String>?
) {
    fun role(key: String): RoleDef? = roles[key]
    fun page(id: String): PageDef? = pages[id]

    companion object {
        fun parse(json: String): PortalConfig = Gson().fromJson(json, PortalConfig::class.java)
    }
}

data class RoleDef(val title: String, val hero: String?, val home: String, val folder: String?, val nav: List<String>)

data class PageDef(
    val id: String,
    val title: String,
    val subtitle: String?,
    val type: String,
    val endpoint: String?,
    val dataPath: String?,
    val params: Map<String, String>?,
    val search: Boolean?,
    val searchParam: String?,
    val searchLabel: String?,
    val filters: List<FilterDef>?,
    val columns: List<ColumnDef>?,
    val create: CreateDef?,
    val actions: List<ActionDef>?,
    val export: ExportDef?,
    val upload: UploadDef?,
    val reports: List<List<String>>?,
    val fields: List<FieldDef>?,
    val method: String?,
    val filterRows: Map<String, List<JsonElement>>?
) {
    val showSearch: Boolean get() = search == true || searchParam != null
}

data class FilterDef(val param: String, val label: String, val options: List<JsonElement>)
data class ColumnDef(val label: String, val field: String, val type: String?)
data class OptionsFrom(val url: String, val path: String?, val value: String, val label: String, val tpl: String?)

data class FieldDef(
    val name: String,
    val label: String,
    val type: String,
    val required: Boolean?,
    val optional: Boolean?,
    val from: String?,
    val options: List<JsonElement>?,
    val optionsFrom: OptionsFrom?,
    val cast: String?,
    val hint: String?,
    val step: String?
)

data class FormDef(val title: String, val fields: List<FieldDef>)
data class CreateDef(val label: String, val title: String, val method: String?, val url: String, val fields: List<FieldDef>)
data class ExportDef(val label: String, val url: String, val filename: String?)
data class UploadDef(val label: String, val url: String)
data class DetailField(val label: String, val path: String, val type: String?)
data class DetailList(val title: String, val path: String, val scalar: Boolean?, val columns: List<ColumnDef>?)
data class DetailDef(val title: String, val url: String?, val fields: List<DetailField>?, val lists: List<DetailList>?)

data class ActionDef(
    val label: String,
    val icon: String?,
    val type: String?,
    val method: String?,
    val url: String?,
    val body: JsonObject?,
    val bodyFromRow: Map<String, String>?,
    val form: FormDef?,
    val confirm: String?,
    val danger: Boolean?,
    @SerializedName("when") val whenMap: Map<String, List<JsonElement>>?,
    val detail: DetailDef?,
    val field: String?,
    val originField: String?,
    val filename: String?
)

/** Screen / action / field kinds the Android engine knows how to render. The contract test checks the config only uses these. */
object Supported {
    val pageTypes = setOf("dashboard", "table", "tracking", "reports", "notifications", "profile", "company", "settings-form")
    val actionTypes = setOf("detail", "download", "navigate")
    val fieldTypes = setOf("text", "email", "password", "number", "date", "datetime", "textarea", "select", "checkbox")
    val columnTypes = setOf("text", "strong", "money", "date", "datetime", "number", "kg", "km", "bool", "lowstock", "count", "status", "route")
}

/** Option shown in a dropdown. */
data class Choice(val value: String, val label: String)

fun FieldDef.staticChoices(): List<Choice> = (options ?: emptyList()).map { o ->
    if (o.isJsonObject) Choice(o.asJsonObject.get("value").asString, o.asJsonObject.get("label").asString)
    else Choice(o.asString, Logic.label(o.asString))
}

fun FilterDef.choices(): List<Choice> = options.map { o ->
    if (o.isJsonObject) Choice(o.asJsonObject.get("value").asString, o.asJsonObject.get("label").asString)
    else Choice(o.asString, Logic.label(o.asString))
}
